CREATE FUNCTION guard_workspace() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.status = 'PURGED' AND NEW.status IS DISTINCT FROM OLD.status THEN
  RAISE EXCEPTION 'a purged workspace keeps its status' USING ERRCODE = '55000';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER workspace_transition BEFORE UPDATE OF status ON workspace FOR EACH ROW EXECUTE FUNCTION guard_workspace();
